"""Build public documentation pages using fictional data and the shipped theme assets."""
from pathlib import Path
from html import escape

root=Path(__file__).resolve().parents[1]
output=root/'docs/demo';output.mkdir(parents=True,exist_ok=True)
media='../../htdocs/luci-static/tealdark'
def table(rows):return '<table class="table">'+''.join('<tr class="tr"><td class="td">'+escape(k)+'</td><td class="td">'+v+'</td></tr>'for k,v in rows)+'</table>'
def meter(value,text):return '<div class="cbi-progressbar" title="'+escape(text,quote=True)+'"><div style="width:'+str(value)+'%"></div></div>'
def section(title,body,anchor):return '<div class="cbi-section" id="'+anchor+'"><div class="cbi-title"><h3>'+title+'</h3></div><div>'+body+'</div></div>'
def badge(icon,body):return '<div class="ifacebadge"><img src="'+media+'/icons/'+icon+'.svg" alt=""><span>'+body+'</span></div>'
def card(title,rows,footer):
 info='<br>'.join('<strong>'+escape(k)+':</strong> '+escape(v)for k,v in rows)
 return '<div class="ifacebox"><div class="ifacebox-head"><strong>'+title+'</strong></div><div class="ifacebox-body left"><span>'+info+'</span>'+footer+'</div></div>'
system=section('System',table([('Hostname','OpenWrt'),('Model','Example Router'),('Architecture','ARM64'),('Firmware','OpenWrt SNAPSHOT'),('Kernel','6.x'),('Uptime','2d 04h 12m'),('Load average','0.02, 0.04, 0.01')]),'system')
memory=section('Memory',table([('Available',meter(64,'328 MiB / 512 MiB (64%)')),('Used',meter(36,'184 MiB / 512 MiB (36%)')),('Buffered',meter(2,'10 MiB / 512 MiB (2%)')),('Cached',meter(18,'92 MiB / 512 MiB (18%)'))]),'memory')
network=section('Network','<div class="network-status-table">'+card('IPv4 Upstream',[('Protocol','DHCP client'),('Address','192.0.2.10/24'),('Gateway','192.0.2.1'),('DNS','192.0.2.53'),('Connected','2d 04h 12m')],badge('tunnel','<strong>Device:</strong> WAN interface'))+card('IPv6 Upstream',[('Protocol','DHCPv6 client'),('Prefix delegated','2001:db8:1200::/56'),('Address','2001:db8:1234:5678:abcd:ef01:2345:6789/64'),('Gateway','fe80::1'),('Connected','2d 04h 12m')],badge('tunnel','<strong>Device:</strong> IPv6 WAN interface'))+'</div>','network')
wireless=section('Wireless','<div class="network-status-table">'+card('radio0',[('Type','802.11ax Wireless Adapter'),('Bitrate','1201 Mbit/s'),('Channel','36 (5.180 GHz)'),('Country','Example profile'),('Noise','-96 dBm')],badge('signal-4','<strong>SSID:</strong> Example-5G<br><strong>Mode:</strong> Access Point<br><strong>Encryption:</strong> WPA2 PSK (CCMP)<br><strong>Clients:</strong> 2'))+card('radio1',[('Type','802.11ax 2.4 GHz Wireless Adapter'),('Channel','6 (2.437 GHz)')],badge('signal-3','<strong>SSID:</strong> Example-2G<br><strong>Mode:</strong> Access Point<br><strong>Encryption:</strong> WPA2 PSK (CCMP)'))+'</div>','wireless')
actions='''<div class="cbi-page-actions"><div class="cbi-dropdown btn cbi-button cbi-button-apply important" tabindex="0"><ul><li selected display="0">Save &amp; Apply</li></ul><span class="open">▾</span></div><button class="cbi-button cbi-button-save" type="button">Save</button><button class="cbi-button cbi-button-reset" type="button">Reset</button></div>'''
head='''<!doctype html><html lang="en" data-theme="light" data-darkmode="false"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TealDark — demonstration</title><link rel="stylesheet" href="'''+media+'''/cascade.css"><script src="'''+media+'''/appearance.js"></script></head><body class="td modern" data-page="admin-status-overview"><header class="modern-top"><a class="modern-brand" href="index.html">open<span>wrt</span><small>DEMO</small></a><button class="menu-toggle" id="td-menu-toggle" type="button" aria-controls="modern-sidebar" aria-expanded="false" aria-label="Toggle menu">☰</button><div class="modern-top-right"><div id="indicators"><span class="label">Example data</span></div><select id="td-appearance" aria-label="Appearance"><option value="auto">Automatic</option><option value="light">Light</option><option value="dark">Dark</option></select></div></header><button class="td-menu-backdrop" id="td-menu-backdrop" type="button" aria-label="Close menu" hidden></button><aside class="modern-sidebar" id="modern-sidebar"><div class="sidebar-label">ROUTER MANAGEMENT</div><nav id="topmenu"><details class="nav-group" open><summary>Status</summary><div class="nav-children"><a class="nav-link selected" href="index.html">Overview</a><a class="nav-link" href="network.html">Network</a><a class="nav-link" href="wireless.html">Wireless</a></div></details><details class="nav-group"><summary>System</summary><div class="nav-children"><a class="nav-link" href="#system">System</a><a class="nav-link" href="#memory">Administration</a></div></details><details class="nav-group"><summary>Services</summary></details><details class="nav-group"><summary>Network</summary></details></nav><div class="sidebar-footer"><span class="sidebar-dot"></span>TealDark preview<small>Fictional documentation data</small></div></aside><main id="maincontent" class="container modern-content"><h2>'''
tail='''</main><footer class="modern-footer">TealDark for modern LuCI · Documentation preview using fictional data</footer></body></html>'''
for filename,title,body in [('index.html','Overview',system+memory+network),('network.html','Network',network),('wireless.html','Wireless',wireless)]:
 page=head+title+'</h2><p class="page-subtitle">A light, responsive interface for your OpenWrt router.</p><div id="view">'+body+'</div>'
 if filename!='index.html':page=page.replace('data-page="admin-status-overview"','data-page="tealdark-demo"')+actions
 (output/filename).write_bytes((page+tail).encode())
print('PUBLIC_DEMO_PAGES_BUILT_WITH_FICTIONAL_DATA')
